import os
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter

path='/root/data/workbook.xlsx'
wb=load_workbook(path, data_only=False)
print('Sheets:', wb.sheetnames)

def sheet_dims(ws, max_rows=80, max_cols=60):
    max_r = 0
    max_c = 0
    for r in range(1, max_rows+1):
        for c in range(1, max_cols+1):
            v = ws.cell(r,c).value
            if v is not None and v!='':
                max_r=max(max_r,r)
                max_c=max(max_c,c)
    return max_r, max_c

wsD=wb['Data']
wsT=wb['Task']
print('Data dims (scan 80x60):', sheet_dims(wsD))
print('Task dims (scan 80x60):', sheet_dims(wsT))


def row_values(ws, r, max_c=60):
    vals=[]
    for c in range(1, max_c+1):
        vals.append(ws.cell(r,c).value)
    while vals and (vals[-1] is None or vals[-1]==''):
        vals.pop()
    return vals

print('\nData row 1:')
print(row_values(wsD,1,60))

print('\nData rows 20-40:')
for r in range(20,41):
    vals=row_values(wsD,r,60)
    if vals:
        print(f'Data row {r}:', vals)

# Data rows 21-38 completely (all columns with data)
print('\nData rows 21-38 with columns:')
last_col=0
for r in range(21,39):
    for c in range(1,61):
        v=wsD.cell(r,c).value
        if v is not None and v!='':
            last_col=max(last_col,c)
print('last_col in 21-38:', last_col, get_column_letter(last_col))
headers=[get_column_letter(c) for c in range(1,last_col+1)]
print('Cols:', headers)
for r in range(21,39):
    vals=[wsD.cell(r,c).value for c in range(1,last_col+1)]
    print(r, vals)

print('\nTask row 10 (A-T):')
print([wsT.cell(10,c).value for c in range(1,21)])

for block, (r1,r2) in enumerate([(12,17),(19,24),(26,31)], start=1):
    print(f'\nTask block {block} rows {r1}-{r2} cols A-G:')
    for r in range(r1,r2+1):
        print(r, [wsT.cell(r,c).value for c in range(1,8)])
    print(f'Task block {block} series codes D{r1}:D{r2}:', [wsT.cell(r,4).value for r in range(r1,r2+1)])

print('\nTask rows 35-40 cols A-G:')
for r in range(35,41):
    print(r, [wsT.cell(r,c).value for c in range(1,8)])

print('\nTask rows 42-47 cols A-G:')
for r in range(42,48):
    print(r, [wsT.cell(r,c).value for c in range(1,8)])

print('\nTask row 50 cols A-G:')
print([wsT.cell(50,c).value for c in range(1,8)])

# check fills
from openpyxl.styles.colors import Color

def fill_sig(cell):
    f=cell.fill
    if f is None:
        return None
    pat=getattr(f,'patternType',None) or getattr(f,'fill_type',None)
    fg=getattr(f,'fgColor',None)
    bg=getattr(f,'bgColor',None)
    def color_to_str(col):
        if col is None:
            return None
        if getattr(col,'type',None) == 'rgb':
            return col.rgb
        if getattr(col,'type',None) == 'indexed':
            return f'indexed:{col.indexed}'
        if getattr(col,'type',None) == 'theme':
            return f'theme:{col.theme}:{col.tint}'
        return str(col)
    return (pat, color_to_str(fg), color_to_str(bg))

for (r1,r2) in [(12,17),(19,24),(26,31)]:
    print(f'\nFills for Task H{r1}:L{r2} first row sample:')
    for c in range(8,13):
        cell=wsT.cell(r1,c)
        print(cell.coordinate, fill_sig(cell), 'val', cell.value)

